/**
 * Inventario visual Wayuu V3.
 *
 * Fuente: lectura completa de Mito, Historia, Versiones y research_notes de los
 * 27 registros editoriales en Neon. El inventario separa detectar de decidir:
 * toda entidad relevante queda registrada, aunque su disposicion visual sea
 * modelo propio, cobertura dentro de otra ficha o exclusion documentada.
 */

const STATEFUL_KINDS = new Set(["personaje", "deidad_fuerza", "criatura", "animal"]);

function defaultRequirements(kind, states) {
  const base = {
    personaje: "identity_sheet",
    deidad_fuerza: "presence_model",
    criatura: "identity_sheet",
    animal: "identity_sheet",
    colectivo: "group_grammar",
    objeto: "object_sheet",
    planta: "botanical_sheet",
    arquitectura: "spatial_model",
    lugar: "spatial_model",
    paisaje: "environment_model",
    fenomeno: "phenomenon_rule",
  }[kind];
  return STATEFUL_KINDS.has(kind) && states.length > 1 ? [base, "state_sheet"] : [base];
}

function e(id, name, kind, description, options = {}) {
  const states = options.states || ["canonico"];
  const visualStatus = options.visualStatus || "required";
  return {
    id,
    name,
    kind,
    description,
    aliases: options.aliases || [],
    states,
    evidence_basis: options.basis || "documented",
    sensitivity: options.sensitivity || "public",
    visual_status: visualStatus,
    model_requirements: visualStatus === "required" ? (options.requirements || defaultRequirements(kind, states)) : [],
    model_refs: [],
    legacy_model_refs: options.legacy || [],
    ...(visualStatus === "embedded" ? {
      covered_by: options.coveredBy,
      coverage_note: options.coverageNote,
    } : {}),
    ...(visualStatus === "excluded" ? { exclusion_reason: options.exclusionReason } : {}),
  };
}

