const refsByEntity = new Map(ENTITY_DEFS.map((entity) => [entity.id, []]));
for (const [slug, myth] of Object.entries(MYTH_DEFS)) {
  for (const ref of myth.refs) {
    if (!refsByEntity.has(ref.entity_id)) throw new Error(`Entidad no definida en ${slug}: ${ref.entity_id}`);
    refsByEntity.get(ref.entity_id).push({ slug, note: ref.note });
  }
}

const entities = Object.fromEntries(ENTITY_DEFS.map((entity) => {
  const refs = refsByEntity.get(entity.id);
  if (!refs.length) throw new Error(`Entidad sin mito consumidor: ${entity.id}`);
  const { id, ...definition } = entity;
  return [id, {
    ...definition,
    myth_refs: [...new Set(refs.map((item) => item.slug))],
    evidence: refs.map((item) => ({ myth: item.slug, field: "mito", note: item.note })),
  }];
}));

const myths = Object.fromEntries(Object.entries(MYTH_DEFS).map(([slug, myth]) => [slug, {
  title: myth.title,
  extraction: {
    reviewed_fields: ["mito", "historia", "versiones", "research_notes"],
    passes: EXTRACTION_PASSES,
    unresolved_mentions: [],
    review_status: "editorial_approved",
    reviewed_at: "2026-09-03",
    note: myth.note,
  },
  entity_refs: myth.refs,
}]));

